  insert into pg_temp.t9_import_rows values
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-001', 't9:2026-09-03:TOAN-6:HS06-001', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 5, 5, 2, '2.0', 'Bạn Ngân ngồi học rất  ngoan chăm chú nghe giảng hiểu bản chất vấn đề và nắm được kiến thức cơ bản.Tuy nhiên trong lúc làm BT có khá ẩu dẫn đến sai sót. Bạn cần luyện tập các dạng bài thêm nhiều hơn và rèn kĩ năng cẩn thận hơn', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":6,"student_code":"HS06-001","source_name":"Đào Thị Kim Ngân","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":"2.0","homework_raw":null,"understanding_raw":"5.0","attitude_raw":"5.0","comment_raw":"Bạn Ngân ngồi học rất  ngoan chăm chú nghe giảng hiểu bản chất vấn đề và nắm được kiến thức cơ bản.Tuy nhiên trong lúc làm BT có khá ẩu dẫn đến sai sót. Bạn cần luyện tập các dạng bài thêm nhiều hơn và rèn kĩ năng cẩn thận hơn"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-002', 't9:2026-09-03:TOAN-6:HS06-002', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Phương Anh là bạn rất chăm chú nghe giảng và luôn tích cực phát biểu xây dựng bài. Bạn nắm chắc kiến thức cơ bản, tuy nhiên bạn còn rất ẩu dẫn đến những sai sót không đáng có trong quá trình làm bài. Bạn cần rèn luyện tính cẩn thận nhiều hơn.', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":7,"student_code":"HS06-002","source_name":"Đặng Phương Anh","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Phương Anh là bạn rất chăm chú nghe giảng và luôn tích cực phát biểu xây dựng bài. Bạn nắm chắc kiến thức cơ bản, tuy nhiên bạn còn rất ẩu dẫn đến những sai sót không đáng có trong quá trình làm bài. Bạn cần rèn luyện tính cẩn thận nhiều hơn."}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-003', 't9:2026-09-03:TOAN-6:HS06-003', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Bạn Bảo đã có tiến bộ hơn về ý thức học tập, bạn đã tự giác làm bài và chăm chú nghe giảng hơn và nắm được các kiến thức cơ bản. Tuy nhiên đôi lúc bạn còn thiếu sự tập trung nên tốc độ làm bài còn chậm hơn các bạn. Bạn cần tập trung cao độ hơn trong các buổi học sau để đạt hiểu quả cao hơn.', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":8,"student_code":"HS06-003","source_name":"Nguyễn Gia Bảo","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Bạn Bảo đã có tiến bộ hơn về ý thức học tập, bạn đã tự giác làm bài và chăm chú nghe giảng hơn và nắm được các kiến thức cơ bản. Tuy nhiên đôi lúc bạn còn thiếu sự tập trung nên tốc độ làm bài còn chậm hơn các bạn. Bạn cần tập trung cao độ hơn trong các buổi học sau để đạt hiểu quả cao hơn."}'::jsonb),
