    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-008', 't9:2026-09-03:TOAN-6:HS06-008', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, 1, '1.0', 'Tú tuy vào học sau so với các bạn nhưng bạn nắm khá chắc kiến thức và mạnh dạn hỏi những bài chưa được học và chưa hiểu.Bạn cần phát huy tinh thần học tập này', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":13,"student_code":"HS06-008","source_name":"Nguyễn Ngọc Cẩm Tú","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":"1.0","homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Tú tuy vào học sau so với các bạn nhưng bạn nắm khá chắc kiến thức và mạnh dạn hỏi những bài chưa được học và chưa hiểu.Bạn cần phát huy tinh thần học tập này"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-009', 't9:2026-09-03:TOAN-6:HS06-009', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, 3, '3.0', 'Bạn Hoàng đã có tiến bộ hơn về ý thức học tập, bạn đã tự giác làm bài và chăm chú nghe giảng hơn và nắm được các kiến thức cơ bản. Tuy nhiên đôi lúc bạn còn thiếu sự tập trung nên tốc độ làm bài còn chậm hơn các bạn. Bạn cần tập trung cao độ hơn trong các buổi học sau để đạt hiểu quả cao hơn.', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":14,"student_code":"HS06-009","source_name":"Đào Thế Hoàng","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":"3.0","homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Bạn Hoàng đã có tiến bộ hơn về ý thức học tập, bạn đã tự giác làm bài và chăm chú nghe giảng hơn và nắm được các kiến thức cơ bản. Tuy nhiên đôi lúc bạn còn thiếu sự tập trung nên tốc độ làm bài còn chậm hơn các bạn. Bạn cần tập trung cao độ hơn trong các buổi học sau để đạt hiểu quả cao hơn."}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-010', 't9:2026-09-03:TOAN-6:HS06-010', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 5, 5, NULL, NULL, 'Bình An là một bạn khá thông minh, chăm chú nghe giảng. Tuy nhiên bạn còn rất ẩu trong quá trình làm bài khiến làm bài sai khá nhiều.Bạn cần rèn luyện tính cẩn thận để đạt kết quả cao hơn', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":15,"student_code":"HS06-010","source_name":"Đào Nguyễn Bình An","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"5.0","attitude_raw":"5.0","comment_raw":"Bình An là một bạn khá thông minh, chăm chú nghe giảng. Tuy nhiên bạn còn rất ẩu trong quá trình làm bài khiến làm bài sai khá nhiều.Bạn cần rèn luyện tính cẩn thận để đạt kết quả cao hơn"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-011', 't9:2026-09-03:TOAN-6:HS06-011', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'My đã có tiến bộ hơn nắm đa số kiến thức cơ bản đã học.Bạn cần rèn luyện thêm các kiến thức để đạt kết quả cao hơn', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":16,"student_code":"HS06-011","source_name":"Nguyễn Trà My","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"My đã có tiến bộ hơn nắm đa số kiến thức cơ bản đã học.Bạn cần rèn luyện thêm các kiến thức để đạt kết quả cao hơn"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-012', 't9:2026-09-03:TOAN-6:HS06-012', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Dũng đã có tiến bộ hơn khá nhiều so với những buổi đầu vào học cùng các bạn.Tuy nhiên các kiến thức cơ bản của bạn còn chưa nắm vững nên đôi lúc làm bài còn khá ;úng túng.Bạn cần ôn lại các kiến thức đã học để đạt kiến quả tốt hơn', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":17,"student_code":"HS06-012","source_name":"Bảo Dũng","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Dũng đã có tiến bộ hơn khá nhiều so với những buổi đầu vào học cùng các bạn.Tuy nhiên các kiến thức cơ bản của bạn còn chưa nắm vững nên đôi lúc làm bài còn khá ;úng túng.Bạn cần ôn lại các kiến thức đã học để đạt kiến quả tốt hơn"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-013', 't9:2026-09-03:TOAN-6:HS06-013', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Minh là một trong những bạn khá thông minh trong lớp, đôi lúc bạn có những ý tưởng giải bài khá tốt, rất chăm chú nghe giảng và tự giác làm bài. Bạn cần tiếp tục duy trì phong độ học tập này', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":18,"student_code":"HS06-013","source_name":"Đào Quang Minh","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Minh là một trong những bạn khá thông minh trong lớp, đôi lúc bạn có những ý tưởng giải bài khá tốt, rất chăm chú nghe giảng và tự giác làm bài. Bạn cần tiếp tục duy trì phong độ học tập này"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-014', 't9:2026-09-03:TOAN-6:HS06-014', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Bạn Duy có ý thức học tập khá tốt,khá tập trung vào bài.Tuy nhiên bạn đôi lúc chưa tự giác làm những bài được giao và chưa tập trung vào buổi học.Bạn cần tập trung vào buổi học và tự giác học và làm bài hơn để đạt hiệu quả cao hơn trong buổi học', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":19,"student_code":"HS06-014","source_name":"Duy","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Bạn Duy có ý thức học tập khá tốt,khá tập trung vào bài.Tuy nhiên bạn đôi lúc chưa tự giác làm những bài được giao và chưa tập trung vào buổi học.Bạn cần tập trung vào buổi học và tự giác học và làm bài hơn để đạt hiệu quả cao hơn trong buổi học"}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-015', 't9:2026-09-03:TOAN-6:HS06-015', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Bạn Phúc rất chăm chú nghe giảng, tiếp thu bài tốt và tích cực tham gia xây dựng bài. Bạn có thái độ học tập nghiêm túc và chủ động, đây là điểm rất đáng khen. Hãy tiếp tục phát huy tinh thần này để ngày càng tiến bộ.', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":20,"student_code":"HS06-015","source_name":"Phúc","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Bạn Phúc rất chăm chú nghe giảng, tiếp thu bài tốt và tích cực tham gia xây dựng bài. Bạn có thái độ học tập nghiêm túc và chủ động, đây là điểm rất đáng khen. Hãy tiếp tục phát huy tinh thần này để ngày càng tiến bộ."}'::jsonb),
    ('TOAN-6', '2026-09-03', '17:30'::time, '19:30'::time, 'HS06-016', 't9:2026-09-03:TOAN-6:HS06-016', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, 4, 5, NULL, NULL, 'Bạn Thảo Linh có ý thức sửa sai tốt và đã rất cố gắng hoàn thiện lại những câu còn mắc lỗi. Tuy nhiên, đôi lúc bạn vẫn còn hơi ẩu khi làm bài nên dễ dẫn đến sai sót. Bạn cần đọc kỹ đề, kiểm tra lại từng bước trước khi kết luận để hạn chế những lỗi không đáng có.', '{"import_batch":"t9_2026_09","source_file":"Diem_danh_6.xlsm","source_sheet":"Form đánh giá","source_block":"J5","source_row":21,"student_code":"HS06-016","source_name":"Linh","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":"4.0","attitude_raw":"5.0","comment_raw":"Bạn Thảo Linh có ý thức sửa sai tốt và đã rất cố gắng hoàn thiện lại những câu còn mắc lỗi. Tuy nhiên, đôi lúc bạn vẫn còn hơi ẩu khi làm bài nên dễ dẫn đến sai sót. Bạn cần đọc kỹ đề, kiểm tra lại từng bước trước khi kết luận để hạn chế những lỗi không đáng có."}'::jsonb),
