    ('TOAN-9', '2026-09-10', '17:30'::time, '19:30'::time, 'HS09-004', 't9:2026-09-10:TOAN-9:HS09-004', 'Có mặt', 'PRESENT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"import_batch":"t9_2026_09","source_file":"Diem_danh_9.xlsm","source_sheet":"Form đánh giá ","source_block":"O5","source_row":9,"student_code":"HS09-004","source_name":"Anh Trọng","status_raw":"Có mặt","attendance_status":"PRESENT","positive_feedback_raw":null,"homework_raw":null,"understanding_raw":null,"attitude_raw":null,"comment_raw":null}'::jsonb),
